import { computed, defineComponent, h, type PropType } from 'vue';
import { getInputGroupAddonStyleKeys, getInputGroupStyleKeys, inputGroupStyleKeys } from '../lib/core';
import type { InputGroupAddonAlign, InputGroupVariant, ButtonVariant, ButtonSize } from '../lib/core';
import styles from './input-group.module.scss';
import { Button } from '../button';

export const InputGroup = defineComponent({
	name: 'InputGroup',
	props: {
		variant: {
			type: String as PropType<InputGroupVariant>,
			default: 'default',
		},
	},
	setup(props, { slots, attrs }) {
		const styleKeys = computed(() => getInputGroupStyleKeys(props.variant));
		const classes = computed(() => [styles[styleKeys.value.base], styles[styleKeys.value.variant]]);

		return () => h('div', { ...attrs, role: 'group', 'data-slot': 'input-group', 'data-variant': props.variant, class: [...classes.value, attrs.class] }, slots.default?.());
	},
});

export const InputGroupAddon = defineComponent({
	name: 'InputGroupAddon',
	props: {
		variant: {
			type: String as PropType<InputGroupVariant>,
			default: 'default',
		},
		align: {
			type: String as PropType<InputGroupAddonAlign>,
			default: 'inline-start',
		},
	},
	setup(props, { slots, attrs }) {
		const styleKeys = computed(() => getInputGroupAddonStyleKeys(props.variant));
		const classes = computed(() => [styles[styleKeys.value.base], styles[styleKeys.value.variant]]);

		function handleClick(event: MouseEvent) {
			const target = event.target as HTMLElement;
			if (target.closest('button')) {
				return;
			}
			(event.currentTarget as HTMLElement).parentElement?.querySelector('input')?.focus();
		}

		return () =>
			h(
				'div',
				{
					...attrs,
					role: 'group',
					'data-slot': 'input-group-addon',
					'data-variant': props.variant,
					'data-align': props.align,
					class: [...classes.value, attrs.class],
					onClick: handleClick,
				},
				slots.default?.(),
			);
	},
});

export const InputGroupButton = defineComponent({
	name: 'InputGroupButton',
	props: {
		variant: {
			type: String as PropType<ButtonVariant>,
			default: 'ghost',
		},
		size: {
			type: String as PropType<ButtonSize>,
			default: 'sm',
		},
		type: {
			type: String as PropType<'button' | 'submit' | 'reset'>,
			default: 'button',
		},
	},
	setup(props, { slots, attrs }) {
		return () =>
			h(
				Button,
				{
					...attrs,
					type: props.type,
					variant: props.variant,
					size: props.size,
					class: [styles[inputGroupStyleKeys.button], attrs.class],
				},
				() => slots.default?.(),
			);
	},
});

export const InputGroupText = defineComponent({
	name: 'InputGroupText',
	setup(_props, { slots, attrs }) {
		return () => h('span', { ...attrs, 'data-slot': 'input-group-text', class: [styles[inputGroupStyleKeys.text], attrs.class] }, slots.default?.());
	},
});

export const InputGroupInput = defineComponent({
	name: 'InputGroupInput',
	props: {
		modelValue: String,
		placeholder: String,
		disabled: { type: Boolean, default: false },
	},
	emits: ['update:modelValue', 'change'],
	setup(props, { emit, attrs }) {
		function handleInput(event: Event) {
			emit('update:modelValue', (event.target as HTMLInputElement).value);
		}

		return () =>
			h('input', {
				...attrs,
				'data-slot': 'input-group-control',
				value: props.modelValue,
				placeholder: props.placeholder,
				disabled: props.disabled,
				class: [styles[inputGroupStyleKeys.input], attrs.class],
				onInput: handleInput,
			});
	},
});

export const InputGroupTextarea = defineComponent({
	name: 'InputGroupTextarea',
	props: {
		modelValue: String,
		placeholder: String,
		disabled: { type: Boolean, default: false },
	},
	emits: ['update:modelValue', 'change'],
	setup(props, { emit, attrs }) {
		function handleInput(event: Event) {
			emit('update:modelValue', (event.target as HTMLTextAreaElement).value);
		}

		return () =>
			h('textarea', {
				...attrs,
				'data-slot': 'input-group-control',
				value: props.modelValue,
				placeholder: props.placeholder,
				disabled: props.disabled,
				class: [styles[inputGroupStyleKeys.textarea], attrs.class],
				onInput: handleInput,
			});
	},
});

export default InputGroup;

@use '../../../styles/variables/colors' as *;

.inputGroup {
	position: relative;
	display: flex;
	width: 100%;
	align-items: center;
	border-radius: var(--tile-input-group-radius, #{$radius});
	border: var(--tile-input-group-border-width, 1px) solid var(--tile-input-group-border, #{$input});
	transition:
		border-color $transition-fast,
		box-shadow $transition-fast;
	outline: none;

	&:focus-within {
		border-color: var(--tile-input-group-focus-border, #{$ring});
		box-shadow: var(--tile-input-group-focus-shadow, 0 0 0 3px color-mix(in srgb, #{$ring} 50%, transparent));
	}

	&:has([aria-invalid='true']) {
		border-color: $destructive;
		box-shadow: var(--tile-input-group-error-shadow, none);

		&:focus-within {
			box-shadow: var(--tile-input-group-error-focus-shadow, 0 0 0 3px color-mix(in srgb, #{$destructive} 20%, transparent));
		}
	}

	&:has(> textarea) {
		align-items: flex-start;
	}

	&:has(> .addon[data-align='block-start'], > .addon[data-align='block-end']) {
		flex-wrap: wrap;
	}

	// 样式变体
	&.variantDefault {
		background-color: var(--tile-input-group-background, transparent);
		box-shadow: var(--tile-input-group-shadow, #{$shadow-sm});

		&:focus-within {
			box-shadow: var(--tile-input-group-focus-shadow, #{$shadow-sm});

			&:has([aria-invalid='true']) {
				box-shadow: var(--tile-input-group-error-focus-shadow, #{$shadow-sm});
			}
		}
	}

	&.variantOutline {
		background-color: var(--tile-input-group-outline-background, #{$field-subtle});
		box-shadow: var(--tile-input-group-outline-shadow, none);

		&:focus-within {
			box-shadow: var(--tile-input-group-focus-shadow, none);

			&:has([aria-invalid='true']) {
				box-shadow: var(--tile-input-group-error-focus-shadow, none);
			}
		}
	}
}

.addon {
	display: flex;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;
	gap: $spacing-2;
	cursor: text;
	padding: $spacing-1_5 0;
	font-size: $text-sm;
	font-weight: $font-medium;
	color: $muted-foreground;
	user-select: none;

	svg {
		pointer-events: none;
		width: 1rem;
		height: 1rem;
	}

	button {
		border-radius: $radius-sm;
	}

	// 样式变体
	&.variantDefault {
		background-color: var(--tile-input-group-addon-background, #{$muted});
	}

	&.variantOutline {
		background-color: transparent;
	}

	// 对齐方式
	&[data-align='inline-start'] {
		order: -1;
		padding-left: $spacing-3;
	}

	&[data-align='inline-end'] {
		order: 1;
		padding-right: $spacing-3;
	}

	&[data-align='block-start'] {
		order: -1;
		flex-basis: 100%;
		width: 100%;
		justify-content: flex-start;
		padding: $spacing-3 $spacing-3 0;

		.inputGroup:has(> input) & {
			padding-bottom: $spacing-2_5;
		}
	}

	&[data-align='block-end'] {
		order: 1;
		flex-basis: 100%;
		width: 100%;
		justify-content: flex-start;
		padding: 0 $spacing-3 $spacing-3;

		.inputGroup:has(> input) & {
			padding-top: $spacing-2_5;
		}
	}
}

.button {
	flex-shrink: 0;
	border-radius: 0;
	border: none;
	box-shadow: none;
}

.text {
	display: flex;
	flex-shrink: 0;
	align-items: center;
	gap: $spacing-2;
	font-size: $text-sm;
	color: $muted-foreground;

	svg {
		pointer-events: none;
		width: 1rem;
		height: 1rem;
	}
}

.input {
	flex: 1;
	min-width: 0;
	height: var(--tile-input-group-height, 2.25rem);
	border: none;
	background-color: transparent;
	padding: 0 $spacing-3;
	font-size: var(--tile-input-group-font-size, #{$text-sm});
	line-height: var(--tile-input-group-line-height, inherit);
	color: $foreground;
	outline: none;

	&::placeholder {
		color: $muted-foreground;
	}

	&:focus-visible {
		outline: none;
	}

	&:disabled {
		pointer-events: none;
		opacity: 0.5;
	}
}

.textarea {
	flex: 1;
	min-width: 0;
	border: none;
	background-color: transparent;
	padding: $spacing-3;
	font-size: var(--tile-input-group-font-size, #{$text-sm});
	line-height: var(--tile-input-group-line-height, inherit);
	color: $foreground;
	resize: none;
	outline: none;

	&::placeholder {
		color: $muted-foreground;
	}

	&:focus-visible {
		outline: none;
	}

	&:disabled {
		pointer-events: none;
		opacity: 0.5;
	}
}
